    fn default() -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        let hardware_specs = format!(
            "CPU: {}\nRAM: {} MB\nGPU: {}",
            system.global_cpu_info().brand(),
            system.total_memory() / 1024 / 1024,
            get_gpu_info()
