        let model_recommendations = vec![
            "LLaMA 7B".to_string(),
            "LLaMA 13B".to_string(),
            "LLaMA 30B".to_string(),
            "LLaMA 65B".to_string(),
        ];

        Self {
            system,
            hardware_specs,
            model_recommendations,
            selected_model: "LLaMA 7B".to_string(),
            text_input: String::new(),
        }
    }
}

impl App {
    pub fn new(cc: &eframe::CreationContext<'_>) -> Self {
        Default::default()
    }
}

