        CentralPanel::default().show(ctx, |ui| {
            ui.heading("AI Writing Evaluator");

            ui.separator();

            ui.label("Hardware Specifications:");
            ui.label(&self.hardware_specs);

            ui.separator();

            ui.label("Model Recommendation:");
