                });

            ui.separator();

            ui.label("Text Input:");
            ui.text_edit_multiline(&mut self.text_input);

            ui.separator();

            if ui.button("Evaluate").clicked() {
                // Placeholder for evaluation logic
                println!("Evaluating text with model: {}", self.selected_model);
            }
        });
    }
}

fn get_gpu_info() -> String {
    // Placeholder for GPU detection logic
    "NVIDIA RTX 3080".to_string()
}
