use crate::hardware::HardwareSpecs;

#[derive(Debug, Clone)]
pub enum ModelSize {
    Llama7B,
    Llama13B,
    Llama30B,
    Llama65B,
}

impl ModelSize {
    fn min_ram_gb(&self) -> u64 {
        match self {
            ModelSize::Llama7B => 12,
            ModelSize::Llama13B => 24,
            ModelSize::Llama30B => 48,
            ModelSize::Llama65B => 96,
        }
    }

    fn recommended_vram_gb(&self) -> f32 {
        match self {
            ModelSize::Llama7B => 4.0,
            ModelSize::Llama13B => 8.0,
            ModelSize::Llama30B => 16.0,
            ModelSize::Llama65B => 32.0,
        }
    }
}

#[derive(Debug, Clone)]
pub struct ModelRecommendation {
    pub model_name: String,
    pub size: ModelSize,
    pub quantization: String,
    pub priority: u8, // Lower number = higher priority
}

pub fn recommend_models(hardware: &HardwareSpecs) -> Vec<ModelRecommendation> {
    let mut recommendations = Vec::new();
    let has_gpu = !hardware.gpu_vram_gb.is_empty();

    // GPU-based recommendations (if available)
    if has_gpu {
        let max_vram_gb = *hardware.gpu_vram_gb.iter().map(|(_, v)| v).max().unwrap_or(&0);

        // Try larger models first
        if max_vram_gb >= 24 {
            recommendations.push(ModelRecommendation {
                model_name: "llama-65b".to_string(),
                size: ModelSize::Llama65B,
                quantization: "Q4_K_M".to_string(),
                priority: 1,
            });
        }

        if max_vram_gb >= 16 {
            recommendations.push(ModelRecommendation {
                model_name: "llama-30b".to_string(),
                size: ModelSize::Llama30B,
                quantization: "Q4_K_M".to_string(),
                priority: 2,
            });
        }

        if max_vram_gb >= 8 {
            recommendations.push(ModelRecommendation {
                model_name: "llama-13b".to_string(),
                size: ModelSize::Llama13B,
                quantization: "Q4_K_M".to_string(),
                priority: 3,
            });
        }

        if max_vram_gb >= 4 {
            recommendations.push(ModelRecommendation {
                model_name: "llama-7b".to_string(),
                size: ModelSize::Llama7B,
                quantization: "Q4_K_M".to_string(),
                priority: 4,
            });
        }
    }

    // CPU/RAM-based recommendations (fallback)
    let ram_gb = hardware.total_ram_gb;
    if ram_gb >= 96 {
        recommendations.push(ModelRecommendation {
            model_name: "llama-65b".to_string(),
            size: ModelSize::Llama65B,
            quantization: "Q4_K_S".to_string(),
            priority: if has_gpu { 10 } else { 1 },
        });
    }

    if ram_gb >= 48 {
        recommendations.push(ModelRecommendation {
            model_name: "llama-30b".to_string(),
            size: ModelSize::Llama30B,
            quantization: "Q4_K_S".to_string(),
            priority: if has_gpu { 11 } else { 2 },
        });
    }

    if ram_gb >= 24 {
        recommendations.push(ModelRecommendation {
            model_name: "llama-13b".to_string(),
            size: ModelSize::Llama13B,
            quantization: "Q4_K_S".to_string(),
            priority: if has_gpu { 12 } else { 3 },
        });
    }

    if ram_gb >= 12 {
        recommendations.push(ModelRecommendation {
            model_name: "llama-7b".to_string(),
            size: ModelSize::Llama7B,
            quantization: "Q4_K_S".to_string(),
            priority: if has_gpu { 13 } else { 4 },
        });
    }

    // Sort by priority and return top recommendation
    let mut sorted = recommendations;
    sorted.sort_by_key(|r| r.priority);
    sorted.dedup_by_key(|r| r.model_name); // Remove duplicates

    if sorted.is_empty() {
        // Absolute minimum requirement
        if ram_gb >= 12 {
            vec![ModelRecommendation {
                model_name: "llama-7b".to_string(),
                size: ModelSize::Llama7B,
                quantization: "Q4_K_S".to_string(),
                priority: 99,
            }]
        } else {
            vec![]
        }
    } else {
        sorted
    }
}
